contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint val) public payable {
        uint before = c.MinSum();
        bool reverted;
        try c.SetMinSum(val) { reverted = false; } catch { reverted = true; }
        uint after_ = c.MinSum();
        assert(!reverted ? after_ == val : after_ == before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint val, bool initializeFirst) public {
        require(address(c) != address(0));

        bool firstReverted;
        bool secondReverted;

        if (initializeFirst) {
            c.Initialized();
            uint beforeMinSum = c.MinSum();
            try c.SetMinSum(val) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            assert(secondReverted && c.MinSum() == beforeMinSum);
        } else {
            try c.SetMinSum(val) {
                firstReverted = false;
            } catch {
                firstReverted = true;
            }
            assert(!firstReverted && c.MinSum() == val);
        }
    }

    receive() external payable {}
}

