contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address logAddr, bool doInit) public {
        // Setup: optionally initialize the contract first.
        if (doInit) {
            c.Initialized();
        }

        bool reverted;
        try c.SetLogFile(logAddr) {
            reverted = false;
        } catch {
            reverted = true;
        }

