contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);
        Log log = new Log();
        c.SetMinSum(0);
        c.SetLogFile(address(log));
        c.Initialized();

        uint beforeBalance = c.Acc(address(this)).balance;
        uint beforeUnlock = c.Acc(address(this)).unlockTime;
        uint beforeTs = block.timestamp;

        bool reverted;
        try c.Put{value: amount}(lockTime) { reverted = false; } catch { reverted = true; }

        uint afterBalance = c.Acc(address(this)).balance;
        uint afterUnlock = c.Acc(address(this)).unlockTime;

        assert(!reverted && afterBalance == beforeBalance + amount && afterUnlock >= beforeTs + lockTime);
    }

    receive() external payable {}
}

