contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _am, uint putAmount, uint lockTime, uint minSum) public payable {
        require(address(this).balance >= putAmount);

        c.SetMinSum(minSum);
        c.Initialized();

        c.Put{value: putAmount}(lockTime);

        (uint unlockTime, uint balance) = c.Acc(address(this));

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(balance >= minSum && balance >= _am && block.timestamp > unlockTime);
        } else {
            assert(balance < minSum || balance < _am || block.timestamp <= unlockTime);
        }
    }

    receive() external payable {}
}

