contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint minSum, uint am, address log) public payable {
        require(address(this).balance >= putAmount);

        c.SetMinSum(minSum);
        c.SetLogFile(log);
        c.Initialized();

        c.Put{value: putAmount}(lockTime);

        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));

        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));

        bool noInitialBalance = balanceBefore == 0;
        bool conditionsMet = balanceBefore >= c.MinSum() && balanceBefore >= am && block.timestamp > unlockBefore;
        bool supported = am <= balanceBefore;

        assert(reverted == (noInitialBalance || !(conditionsMet && supported)));
    }

    receive() external payable {}
}

