contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint firstValue, uint secondValue, uint logAddr) public payable {
        // Ensure we can observe changes only through public getters.
        uint beforeMinSum = c.MinSum();

        // First SetMinSum should succeed because the contract is not initialized yet.
        bool firstReverted;
        try c.SetMinSum(firstValue) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint afterFirstMinSum = c.MinSum();

        // Mark initialized so that a second SetMinSum call will revert.
        c.Initialized();

        beforeMinSum = c.MinSum();

        // Second SetMinSum must revert because the contract is already initialized.
        bool secondReverted;
        try c.SetMinSum(secondValue) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint afterSecondMinSum = c.MinSum();

        assert(!firstReverted && afterFirstMinSum == firstValue && secondReverted && afterSecondMinSum == beforeMinSum);
    }

    receive() external payable {}
}

